a=df['dv_dt'].values; x=df['x'].values; v=df['v'].values; t=df['t'].values
one=np.ones_like(x)
forms={'poly':[x,x*x,x**3],'sin':[np.sin(x),np.cos(x),np.sin(x)*x],'tanh':[np.tanh(x),x*x],'exp':[np.exp(-x),np.exp(-x*x)],'sqrt':[np.sqrt(x),x],'inv':[1/x,x],'log':[np.log(x),x]}
vf=[v,v*np.abs(v),x*v,v*v*v]
for k,fx in forms.items():
    best=(9,0)
    for w in np.arange(0.2,3,0.01):
        X=np.column_stack([one]+fx+vf+[np.cos(w*t),np.sin(w*t),x*np.cos(w*t),x*np.sin(w*t),v*np.cos(w*t),v*np.sin(w*t)])
        c,_,_,_=np.linalg.lstsq(X,a,rcond=None)
        s=np.sum((a-X@c)**2)/np.sum((a-a.mean())**2)
        if s<best[0]: best=(s,w)
    print(k,best)
